+
+  it.each([
+    ["missing key", " ", "gpt-5.6"],
+    ["missing model", "test-key", " "],
+  ])("fails safely for %s", async (_name, apiKey, model) => {
+    const provider = new OpenAIExplanationProvider(apiKey, model);
